"""Batch job dispatcher."""

from dataclasses import dataclass


@dataclass
class PendingJob:
    id: str
    priority: int


def dispatch_batch(pending: list[PendingJob], limit: int = 25) -> list[str]:
    if limit <= 0:
        return []
    ordered = sorted(pending, key=lambda job: job.priority, reverse=True)
    batch_ids = [job.id for job in ordered[:limit]]
    return batch_ids
